/** Relics and themes: the two collections. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    build
 * depends    scripts/game-wiki/render.mjs
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { bullets, heading, recordTable, sections, table } from '../render.mjs'

/** `PROFILE_BANNER` to `Profile Banner`. */
const groupTitle = key =>
  key
    .toLowerCase()
    .split('_')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ')

export function build(context) {
  const { data, knowledge } = context.sdk
  const { format } = context
  const relics = data.RELIC_TEMPLATES
  const types = [...new Set(relics.map(relic => relic.type))]

  context.page(
    'Relics',
    sections(
      `${relics.length} relics.`,
      heading(2, 'How Relics Are Unlocked'),
      table(['Source', 'Details'], data.RELIC_UNLOCK_METHODS.map(method => [method.label, method.description])),
      heading(2, 'Total Bonuses'),
      ...data.RELIC_TOTAL_BONUS_CATEGORIES.map(category =>
        sections(heading(3, category.label), category.description, recordTable(category.rows, format)),
      ),
      ...types.map(type =>
        sections(
          heading(2, `${type} Relics`),
          recordTable(
            relics.filter(relic => relic.type === type),
            format,
            [['name', 'Relic'], ['bonusType', 'Bonus'], 'value', 'rarity', 'event', 'requirement'],
          ),
        ),
      ),
    ),
    { source: ['RELIC_TEMPLATES', 'RELIC_UNLOCK_METHODS', 'RELIC_TOTAL_BONUS_CATEGORIES'] },
  )

  const unreconciled = knowledge.THEME_GROUPS_UNRECONCILED ?? []
  context.page(
    'Themes',
    sections(
      context.overview('themes'),
      heading(2, 'Coin Bonus'),
      data.THEME_PASSIVE_FORMULA,
      table(
        ['Group', 'Bonus per theme owned', 'Themes listed'],
        Object.entries(data.THEMES).map(([key, themes]) => [groupTitle(key), data.THEME_CATEGORY_BONUS[key], themes.length]),
      ),
      unreconciled.length > 0
        ? `The SDK marks these groups as not yet reconciled with the game, so their lists may be incomplete: ${unreconciled.map(groupTitle).join(', ')}.`
        : '',
      ...Object.entries(data.THEMES).map(([key, themes]) => sections(heading(2, groupTitle(key)), recordTable(themes, format))),
      heading(2, 'Where Themes Come From'),
      bullets(data.THEME_CATEGORY_DEFINITIONS.map(definition => `**${definition.label}:** ${definition.unlockSources.join('; ')}`)),
    ),
    { source: ['THEMES', 'THEME_CATEGORY_BONUS', 'THEME_PASSIVE_FORMULA'] },
  )

  context.group('Collections', ['Relics', 'Themes'])
}
